            marcarComoError(aviso, "CORREO_INEXISTENTE");
            continue;
        }

        enviar(aviso, destinatario);
        marcarComoEnviado(aviso);

    } catch (Exception e) {
        log.error("Error procesando aviso id={}", aviso.getId(), e);
        marcarComoError(aviso, e.getMessage());
    }
}
```

No conviene limitarse a hacer:

```java
